const pct=n=>Math.max(0,Math.min(100,Math.round(n.qty/Math.max(1,n.total)*100)));
const fmt=n=>Number(n).toLocaleString('pt-BR');
function tag(v){let cls=/Alta|Pendente/.test(v)?'urgent':/Recebida/.test(v)?'blue':/Recusada/.test(v)?'red':'';return `<span class="tag ${cls}">${esc(v)}</span>`;}
function progress(n){const val=n.kind==='Financeira'?`R$ ${fmt(n.qty)} arrecadados`:`${fmt(n.qty)} de ${fmt(n.total)} atendidos`;return `<div class="spread small"><span class="muted">${val}</span><strong>${pct(n)}%</strong></div><div class="progress" style="margin:8px 0 17px"><i style="width:${pct(n)}%"></i></div>`;}
function toast(msg){const el=$('#toast');if(el)el.innerHTML=`<div class="toast">✓ &nbsp;${esc(msg)}</div>`;setTimeout(()=>{if(el)el.innerHTML=''},3000);}
function navigate(view,id){if(id!==undefined&&id!==null)state.selected=Number(id);state.openHistory=null;state.view=view;window.scrollTo(0,0);render();}
function goDonate(id){state.selected=Number(id);if(state.role==='instituicao'){toast('Saia da conta institucional para fazer uma doação.');return;}if(state.role!=='doador'){state.pendingNeed=state.selected;openAuth('doador');return;}navigate('donate',id);}
function openAuth(role='doador',tab='login'){state.authRole=role;state.authTab=tab;navigate('auth');}
function openInstitution(name){state.selectedOrg=name;navigate('institution');}
function logout(){state.role='visitante';state.pendingNeed=null;state.authRole='doador';navigate('home');toast('Sessão encerrada.');}
function profileIcon(){return `<button class="profile-icon" type="button" aria-label="Abrir meu perfil" title="Meu perfil" onclick="navigate('${state.role==='instituicao'?'instProfile':'donorProfile'}')">♙</button>`;}
function header(){const inside=state.role==='instituicao';const nav=inside?['dashboard','manage','create','instProfile','instEdit'].includes(state.view):false;const logoDest=inside?'dashboard':'home';return `<header class="nav"><div class="navin"><a class="brand" onclick="navigate('${logoDest}')" tabindex="0" onkeydown="if(event.key==='Enter')navigate('${logoDest}')"><span class="mark">✳</span> conectação<span style="color:#7db08c">.</span></a>${inside?`<span class="navlinks" aria-hidden="true"></span><div class="navact">${profileIcon()}</div>`:`<nav class="navlinks" aria-label="Navegação principal"><a class="${state.view==='home'?'active':''}" onclick="navigate('home')">Início</a><a class="${state.view==='explore'?'active':''}" onclick="navigate('explore')">Explorar necessidades</a><a class="${['institutions','institution'].includes(state.view)?'active':''}" onclick="navigate('institutions')">Instituições</a>${state.role==='doador'?`<a class="${state.view==='tracking'?'active':''}" aria-label="Minhas doações" onclick="navigate('tracking')">Minhas doações</a>`:''}</nav><div class="navact">${state.role==='doador'?`<a class="donor-tracking-mobile ${state.view==='tracking'?'active':''}" onclick="navigate('tracking')">Minhas doações</a>`+profileIcon():`<button type="button" class="btn secondary sm" onclick="openAuth('doador')">Entrar</button>`}</div>`}</div></header>`;}
function footer(){return `<footer class="footer"><div class="container spread"><div><a class="brand" onclick="navigate('${state.role==='instituicao'?'dashboard':'home'}')" style="font-size:21px"><span class="mark" style="height:28px;width:28px;font-size:17px;border-radius:9px">✳</span>conectação.</a><p style="margin:8px 0 0">Pequenos gestos. Grandes transformações.</p></div><div style="text-align:right">Protótipo acadêmico de IHC · Dados e instituições fictícios<br>Projeto conceitual para testes de usabilidade · 2026</div></div></footer>`;}
function needCard(n){return `<article class="card need-card"><div class="feature-art" style="background:${n.bg}"><span class="illustration" aria-hidden="true">${n.emoji}</span><div style="position:absolute;top:14px;left:14px">${tag(n.urg)}</div></div><div class="body"><div class="small muted">${esc(n.org)}</div><h3>${esc(n.title)}</h3><p>⌖ ${esc(n.city)} &nbsp;·&nbsp; ${esc(n.cat)}</p><div class="card-bottom">${progress(n)}<button class="btn secondary full" onclick="navigate('need',${n.id})">Ver necessidade ↗</button></div></div></article>`;}
function home(){return `<section class="hero"><div class="container hero-inner"><div><div class="eyebrow">✳ Conexões que transformam</div><h1 class="h1">Sua vontade de ajudar encontra <span style="color:var(--green)">quem precisa.</span></h1><p class="lead">Conectamos pessoas e instituições para transformar solidariedade em impacto real. Descubra onde sua ajuda faz a diferença.</p><div class="hero-actions"><button class="btn" onclick="navigate('explore')">Encontrar onde doar →</button><button class="btn secondary" onclick="openAuth('instituicao')">Sou uma instituição</button></div><div class="hero-mini"><div><strong>+120</strong><small>doações conectadas*</small></div><div><strong>+24</strong><small>necessidades divulgadas*</small></div><div><strong>100%</strong><small>feito com propósito</small></div></div></div><div class="hero-visual"><div class="photo main">🤝</div><div class="photo accent">💚</div><div class="float-box first">🌿 <strong>Uma conexão pode mudar tudo</strong><br><span class="muted small">Faça parte dessa rede</span></div><div class="float-box second">✅ <strong>Doação recebida!</strong><br><span class="muted small">Mais uma história transformada</span></div></div></div></section><div class="strip"><div class="container stripin"><div><span class="iconround dark">♡</span><span><strong>Doações com propósito</strong><br><small>Ajude em necessidades reais</small></span></div><div><span class="iconround dark">◈</span><span><strong>Mais transparência</strong><br><small>Acompanhe o andamento</small></span></div><div><span class="iconround dark">⌖</span><span><strong>Perto de você</strong><br><small>Encontre iniciativas da sua região</small></span></div></div></div><section class="section"><div class="container"><div class="section-top"><div><div class="eyebrow">Faça a diferença hoje</div><h2>Necessidades em destaque</h2><p class="muted">Toda ajuda tem um destino. Encontre uma causa que combine com você.</p></div><button class="btn secondary" onclick="navigate('explore')">Ver todas as necessidades →</button></div><div class="grid3">${needs.slice(0,3).map(needCard).join('')}</div></div></section><section class="section" style="padding-top:10px;background:#f3f7f2"><div class="container"><div class="section-top"><div><div class="eyebrow">Simples, transparente e humano</div><h2>Como funciona?</h2></div></div><div class="grid3 steps"><div class="step"><span class="num">01 ✦</span><h3>Encontre uma causa</h3><p>Explore instituições e necessidades que fazem sentido para você.</p></div><div class="step"><span class="num">02 ✦</span><h3>Ofereça sua ajuda</h3><p>Registre sua intenção de doação diretamente na necessidade escolhida.</p></div><div class="step"><span class="num">03 ✦</span><h3>Acompanhe o impacto</h3><p>Consulte o histórico e as etapas do recebimento da contribuição.</p></div></div></div></section><section class="section"><div class="container"><div class="cta-banner"><div><div class="eyebrow" style="color:#9ed9af">Juntos somos mais fortes</div><h2>Representa uma instituição?</h2><p style="color:#bcd3c6;margin:0">Divulgue necessidades e conecte sua causa a novos apoiadores.</p></div><button class="btn gold" onclick="openAuth('instituicao','register')">Cadastrar instituição →</button></div></div></section><p class="container muted small" style="margin-top:-22px;margin-bottom:45px">*Dados ilustrativos para demonstração do protótipo.</p>`;}
function explore(){let filtered=needs.filter(n=>(state.filter==='Todos'||n.kind===state.filter)&&(state.priority==='Todas'||n.urg===state.priority)&&(!state.city||n.city===state.city)&&(`${n.title} ${n.org} ${n.cat}`.toLowerCase().includes(state.search.toLowerCase())));if(state.order==='urgent')filtered.sort((a,b)=>Number(b.urg==='Alta prioridade')-Number(a.urg==='Alta prioridade'));if(state.order==='recent')filtered.sort((a,b)=>b.id-a.id);const locations=['','Lavras, MG','Ijaci, MG','Perdões, MG'];return `<div class="container"><div class="page-head"><div class="eyebrow">Encontre uma forma de ajudar</div><h1>Explorar necessidades</h1><p class="muted">Pessoas reais podem fazer a diferença com pequenos gestos.</p></div><div class="filters-layout"><aside class="card filter-card"><div class="spread"><h3 style="margin:0">Filtros</h3><button class="clear-btn" onclick="clearFilters()">Limpar</button></div><div class="filter-divider"></div><div role="group" aria-label="Tipo de doação"><label class="label">Tipo de doação</label>${['Todos','Itens','Serviços','Financeira'].map(x=>`<div style="padding:7px 0;font-size:14px"><label><input type="radio" name="kind" ${state.filter===x?'checked':''} onchange="state.filter='${x}';render()" style="accent-color:#277454;margin-right:8px">${x}</label></div>`).join('')}</div><div class="filter-divider"></div><div class="field-group"><label class="label" for="filter-city">Localização</label><select id="filter-city" class="field" onchange="state.city=this.value;render()">${locations.map(x=>`<option value="${x}" ${state.city===x?'selected':''}>${x||'Todas as cidades'}</option>`).join('')}</select></div><div class="field-group"><label class="label" for="filter-priority">Prioridade</label><select id="filter-priority" class="field" onchange="state.priority=this.value;render()"><option value="Todas">Todas</option><option value="Alta prioridade" ${state.priority==='Alta prioridade'?'selected':''}>Alta</option><option value="Moderada" ${state.priority==='Moderada'?'selected':''}>Moderada</option></select></div><div class="callout"><strong>💚 Toda ajuda importa</strong><div class="small" style="margin-top:7px">Não sabe por onde começar? Veja as necessidades com alta prioridade.</div></div></aside><div><form class="searchbar" style="margin-bottom:18px" onsubmit="event.preventDefault();state.search=$('#need-search').value;render()"><input id="need-search" value="${esc(state.search)}" placeholder="Buscar por necessidade, causa ou instituição..." aria-label="Pesquisar necessidades"><button class="btn" type="submit">⌕ Buscar</button></form><div class="results-head"><div><strong>${filtered.length} ${filtered.length===1?'necessidade encontrada':'necessidades encontradas'}</strong><div class="small muted">Exibindo iniciativas disponíveis na plataforma</div></div><select class="field" style="width:185px" aria-label="Ordenar necessidades" onchange="state.order=this.value;render()"><option value="relevant" ${state.order==='relevant'?'selected':''}>Mais relevantes</option><option value="urgent" ${state.order==='urgent'?'selected':''}>Mais urgentes</option><option value="recent" ${state.order==='recent'?'selected':''}>Mais recentes</option></select></div>${filtered.length?`<div class="grid3">${filtered.map(needCard).join('')}</div>`:`<div class="card empty-state"><div style="font-size:38px">🔎</div><h3>Nenhum resultado encontrado</h3><p class="muted">Tente alterar os filtros ou a busca.</p><button class="btn secondary" onclick="clearFilters()">Limpar filtros</button></div>`}</div></div></div>`;}
function clearFilters(){state.filter='Todos';state.city='';state.priority='Todas';state.search='';state.order='relevant';navigate('explore');}
function institutionCard(org){const active=needs.filter(n=>n.org===org.name).length;return `<article class="card institution-card"><div class="art" style="background:${org.bg}">${org.emoji}</div><div class="body"><h3>${esc(org.name)}</h3><p class="muted small" style="margin:0 0 10px">⌖ ${esc(org.city)} · ${esc(org.cat)}</p><p>${esc(org.desc)}</p><div class="small" style="color:#27804c;margin-bottom:13px">♡ ${active} ${active===1?'necessidade ativa':'necessidades ativas'}</div><button class="btn full" onclick="openInstitution('${org.name.replaceAll("'","\\'")}')">Conhecer instituição ↗</button></div></article>`;}
function institutionsPage(){const categories=['Todas','Assistência social','Educação','Animais','Saúde','Meio ambiente'];const filtered=institutions.filter(x=>(state.orgCategory==='Todas'||x.cat===state.orgCategory)&&(`${x.name} ${x.cat} ${x.city}`.toLowerCase().includes(state.orgSearch.toLowerCase())));return `<div class="container"><div class="page-head"><div class="eyebrow">Faça parte dessa rede</div><h1>Instituições que transformam vidas</h1><p class="muted">Conheça organizações da região, descubra suas causas e escolha quem apoiar.</p></div><form class="searchbar" onsubmit="event.preventDefault();state.orgSearch=$('#org-search').value;render()"><input id="org-search" value="${esc(state.orgSearch)}" aria-label="Buscar instituição" placeholder="Buscar por nome, causa ou cidade..."><button type="submit" class="btn">Buscar</button></form><div class="pills" style="margin:19px 0 25px">${categories.map(c=>`<button class="pill ${state.orgCategory===c?'on':''}" onclick="state.orgCategory='${c}';render()">${c}</button>`).join('')}</div><div class="spread" style="margin-bottom:18px"><div><strong>${filtered.length} ${filtered.length===1?'instituição encontrada':'instituições encontradas'}</strong><div class="small muted">Organizações e informações fictícias para avaliação do protótipo.</div></div></div>${filtered.length?`<div class="institution-grid" style="margin-bottom:70px">${filtered.map(institutionCard).join('')}</div>`:`<div class="card empty-state"><h3>Nenhuma instituição encontrada</h3><button class="btn secondary" onclick="state.orgCategory='Todas';state.orgSearch='';render()">Limpar filtros</button></div>`}</div>`;}
function institution(){const org=byOrg(state.selectedOrg);const opened=needs.filter(n=>n.org===org.name);return `<div class="container"><div class="crumb"><a onclick="navigate('home')">Início</a> / <a onclick="navigate('institutions')">Instituições</a> / ${esc(org.name)}</div><section class="institution-hero"><div class="avatar lg" style="background:${org.bg}">${org.emoji}</div><div style="flex:1"><div class="row" style="flex-wrap:wrap"><h1>${esc(org.name)}</h1>${tag('Perfil demonstrativo')}</div><p class="muted" style="margin:7px 0">${esc(org.desc)}</p><div class="small muted">⌖ ${esc(org.city)} · ♡ ${esc(org.cat)} ${org.since?' · Desde '+org.since:''}</div></div></section><div class="detail-grid" style="padding-top:33px"><section><div class="card" style="padding:29px;margin-bottom:29px"><h2 style="font-size:25px">Nossa história</h2><p class="muted" style="margin:0">${esc(org.story)}</p></div><h2 style="font-size:25px">Necessidades abertas</h2><div class="grid3" style="grid-template-columns:repeat(auto-fit,minmax(205px,1fr))">${opened.map(needCard).join('')}</div></section><aside class="card side-card"><h3>Informações da instituição</h3><div class="info-row">⌖ &nbsp; ${esc(org.address)}</div><div class="info-row">♡ &nbsp; Atuação: ${esc(org.cat)}</div><div class="divider"></div><p class="small muted">Os dados são ilustrativos e não representam verificação real.</p><button class="btn secondary full" onclick="navigate('institutions')">← Ver outras instituições</button></aside></div></div>`;}
function needDetail(){const n=byNeed(state.selected);const org=byOrg(n.org);return `<div class="container"><div class="crumb"><a onclick="navigate('home')">Início</a> / <a onclick="navigate('explore')">Necessidades</a> / ${esc(n.title)}</div><div class="detail-grid"><div><div class="detail-cover" style="background:${n.bg}">${n.emoji}</div><div class="detail-body"><div class="row" style="margin-bottom:16px">${tag(n.urg)}<span class="tag grey">${esc(n.kind)}</span><span class="tag grey">${esc(n.cat)}</span></div><h1 style="font-size:38px;letter-spacing:-1.5px;margin-bottom:8px">${esc(n.title)}</h1><p class="muted">⌖ ${esc(n.city)} · Necessidade demonstrativa</p><div class="divider"></div><h2 style="font-size:24px">Sobre essa necessidade</h2><p class="muted" style="line-height:1.85">${esc(n.desc)}</p><h2 style="font-size:24px;margin-top:25px">Como você pode ajudar?</h2><p class="muted">Clique em “Quero ajudar” para registrar sua intenção. A instituição poderá confirmar os detalhes e combinar o recebimento com você.</p><div style="background:#f0f6ef;padding:19px;border-radius:15px;margin-top:25px"><div class="row"><span class="iconround">${org.emoji}</span><div><strong>${esc(n.org)}</strong><div class="small muted">Instituição responsável</div></div><button class="btn ghost sm" style="margin-left:auto" onclick="openInstitution('${n.org.replaceAll("'","\\'")}')">Ver perfil →</button></div></div></div></div><aside class="card side-card"><div class="eyebrow">Uma ajuda que transforma</div><h3 style="font-size:24px;margin:12px 0">${n.kind==='Financeira'?'Progresso da arrecadação':'Progresso da necessidade'}</h3>${progress(n)}<p class="small muted" style="margin:16px 0 22px">Cada contribuição nos aproxima do objetivo.</p><button class="btn full" onclick="goDonate(${n.id})">♡ Quero ajudar →</button><div class="divider"></div><div class="row"><span class="iconround">✓</span><div class="small"><strong>Transparência em cada etapa</strong><br><span class="muted">Acompanhe a confirmação e o recebimento da sua doação.</span></div></div></aside></div><section class="section" style="padding-top:0"><h2 style="font-size:25px">Outras formas de ajudar</h2><div class="grid3">${needs.filter(x=>x.id!==n.id).slice(0,3).map(needCard).join('')}</div></section></div>`;}
function donate(){const n=byNeed(state.selected);const financial=n.kind==='Financeira';const service=n.kind==='Serviços';const measure=financial?'Valor da contribuição (R$)':service?'Disponibilidade (horas)':'Quantidade';return `<div class="container"><div class="crumb"><a onclick="navigate('explore')">Explorar</a> / <a onclick="navigate('need',${n.id})">${esc(n.title)}</a> / Oferecer doação</div><div class="page-head" style="padding-top:10px"><div class="eyebrow">Um gesto de carinho</div><h1>Vamos fazer a diferença?</h1><p class="muted">Preencha as informações para a instituição saber como receber sua ajuda.</p></div><div class="form-layout"><form class="card form-card" onsubmit="submitDonation(event)"><div class="stepper"><i class="on"></i><i class="on"></i><i></i></div><h3>1. Sobre sua doação</h3><div class="formgrid"><div class="field-group"><label class="label">Tipo de doação</label><input class="field" value="${n.kind}" readonly title="Definido pela necessidade selecionada"></div><div class="field-group"><label class="label" for="amount">${measure} *</label><input id="amount" name="amount" class="field" type="number" ${financial?'step="0.01"':'step="1"'} required min="${financial?'0.01':'1'}" placeholder="${financial?'Ex.: 50,00':service?'Ex.: 2':'Ex.: 2'}"></div></div><div class="field-group"><label class="label" for="description">Detalhes do que deseja ${service?'oferecer':'doar'}</label><textarea id="description" name="description" class="field" placeholder="${financial?'Informe observações sobre sua contribuição...':service?'Informe dias, horários e disponibilidade...':'Informe quais itens deseja doar e suas condições de entrega...'}"></textarea></div><div class="divider"></div><h3>2. Como podemos falar com você?</h3><div class="formgrid"><div class="field-group"><label class="label" for="donorName">Nome completo *</label><input class="field" id="donorName" name="donorName" required value="${esc(state.donorName)}"></div><div class="field-group"><label class="label" for="donorEmail">E-mail *</label><input class="field" id="donorEmail" name="donorEmail" type="email" required value="usuario1@teste.com"></div><div class="field-group"><label class="label" for="donorPhone">Telefone *</label><input class="field" id="donorPhone" name="donorPhone" type="tel" required placeholder="(35) 99999-9999" value="(35) 99999-9999"></div><div class="field-group"><label class="label" for="delivery">${financial?'Forma de contribuição':service?'Forma de participação':'Forma preferida de entrega'}</label><select id="delivery" name="delivery" class="field"><option>Combinar com a instituição</option><option>${financial?'Entrar em contato para orientações':service?'Participar presencialmente':'Levar até a instituição'}</option></select></div></div><label class="row small muted" style="margin:10px 0 23px;align-items:start"><input type="checkbox" id="consent" name="consent" required style="accent-color:#277454;margin-top:4px"><span>Concordo em compartilhar estes dados exclusivamente com a instituição para organizar a doação.</span></label><button class="btn full" type="submit">Confirmar intenção de doação →</button><p class="small muted" style="text-align:center;margin:12px 0 0">Sua proposta dependerá de confirmação da instituição.</p></form><aside class="card side-card"><h3>Resumo da sua contribuição</h3><div class="row" style="margin:20px 0"><div class="avatar" style="font-size:25px">${n.emoji}</div><div><strong>${esc(n.title)}</strong><div class="small muted">${esc(n.org)}</div></div></div><div class="divider"></div><div class="summary-line"><span class="muted">Tipo</span><strong>${esc(n.kind)}</strong></div><div class="summary-line"><span class="muted">Localização</span><strong>${esc(n.city)}</strong></div><div class="summary-line"><span class="muted">Status inicial</span>${tag('Pendente')}</div><div class="divider"></div><p class="small muted">🔒 Seus dados serão usados apenas para organizar esta doação no protótipo.</p></aside></div></div>`;}
function submitDonation(event){event.preventDefault();const form=event.currentTarget;const n=byNeed(state.selected);if(!form.reportValidity())return;const data=new FormData(form);const amount=Number(data.get('amount'));if(!(amount>0)){toast('Informe uma quantidade válida.');return;}const id='#ELO-'+String(nextProtocol++).padStart(4,'0');const rec={id,needId:n.id,title:n.title,org:n.org,kind:n.kind,date:'03 nov 2026',status:'Pendente',quantity:n.kind==='Financeira'?`R$ ${fmt(amount)}`:n.kind==='Serviços'?`${amount} hora(s)`:`${amount} unidade(s)`};donations.unshift(rec);proposals.unshift({id:'D-'+(1200+nextProtocol),name:String(data.get('donorName')),item:n.title,date:'03 nov 2026',status:'Pendente',amount:rec.quantity,historyId:id});state.donorName=String(data.get('donorName'));navigate('tracking');state.openHistory=id;render();toast('Intenção registrada! Acompanhe no histórico.');}
function tracking(){return `<div class="container"><div class="page-head"><div class="eyebrow">Acompanhe cada gesto</div><h1>Minhas doações</h1><p class="muted">Veja seu histórico e o andamento de cada contribuição.</p></div><div class="card" style="padding:26px;margin-bottom:65px"><div class="results-head"><div><h3 style="margin:0">Histórico de doações</h3><p class="small muted" style="margin:5px 0 0">${donations.length} registros de demonstração</p></div><button class="btn secondary sm" onclick="navigate('explore')">Explorar necessidades →</button></div><div class="table-card"><table class="table" style="min-width:700px"><thead><tr><th>Protocolo</th><th>Necessidade</th><th>Instituição</th><th>Data</th><th>Status</th><th>Detalhes</th></tr></thead><tbody>${donations.map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td>${esc(x.title)}</td><td>${esc(x.org)}</td><td>${esc(x.date)}</td><td>${tag(x.status)}</td><td><button class="btn secondary sm" onclick="showHistory('${x.id}')">Ver mais</button></td></tr>`).join('')}</tbody></table></div></div></div>`;}
function showHistory(id){state.openHistory=id;render();}
function closeModal(){state.openHistory=null;render();}
function historyModal(){if(!state.openHistory)return '';const d=donations.find(x=>x.id===state.openHistory);if(!d)return '';const stages=['Intenção registrada','Contato confirmado','Entrega combinada','Doação recebida'];const maxStage=d.status==='Pendente'?0:d.status==='Confirmada'?1:d.status==='Entrega combinada'?2:d.status==='Recebida'?3:0;return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><div><h2 id="modal-title" style="font-size:27px;margin:0">Detalhes da doação</h2><div class="muted small">${esc(d.id)} · ${esc(d.date)}</div></div><button class="icon-button" aria-label="Fechar detalhes" onclick="closeModal()">×</button></div><h3 style="font-size:21px">${esc(d.title)}</h3><p class="muted">${esc(d.org)}</p><div class="spread statusline"><strong>Status atual</strong>${tag(d.status)}</div><p class="small muted">${esc(d.quantity)} · ${esc(d.kind)}</p><h3 style="margin-top:24px">Linha do tempo</h3><div class="timeline">${stages.map((x,i)=>`<div class="event ${i<=maxStage?'done':''}"><div class="dot">${i<=maxStage?'✓':i+1}</div><div><strong>${x}</strong><p>${i<=maxStage?'Etapa concluída':'Aguardando andamento da instituição'}</p></div></div>`).join('')}</div>${d.status==='Recusada'?'<p class="tag red">A proposta foi recusada pela instituição.</p>':''}<div class="divider"></div><p class="small muted">Dados fictícios para avaliação do protótipo Conectação.</p><div class="spread"><button class="btn secondary" onclick="closeModal()">Fechar</button><button class="btn" onclick="closeModal();openInstitution('${d.org.replaceAll("'","\\'")}')">Ver instituição →</button></div></section></div>`;}
function donorProfile(){const pending=donations.filter(x=>!['Recebida','Recusada'].includes(x.status)).length,complete=donations.filter(x=>x.status==='Recebida').length;return `<div class="container"><section class="profile-hero"><div class="eyebrow">Minha conta</div><h1>Meu perfil</h1><p class="muted">Acompanhe suas contribuições e mantenha seus dados atualizados.</p></section><div class="card profile-header" style="padding:20px"><div class="avatar" style="background:#153b31;color:#fff">MO</div><div style="flex:1"><h2>${esc(state.donorName)}</h2><div class="muted small">Doadora · Lavras, MG</div></div><button class="btn secondary" onclick="navigate('tracking')">Minhas doações →</button></div><div class="grid3 profile-stats"><div class="statbox"><strong>${donations.length}</strong><span class="caption">Doações registradas</span></div><div class="statbox"><strong>${pending}</strong><span class="caption">Em andamento</span></div><div class="statbox"><strong>${complete}</strong><span class="caption">Concluídas</span></div></div><div class="profile-panel"><div class="card"><h3>Informações pessoais</h3><div class="info-row">Nome completo: ${esc(state.donorName)}</div><div class="info-row">E-mail: usuario1@teste.com</div><div class="info-row">Cidade: Lavras, MG</div></div><div class="card"><h3>Últimas doações</h3>${donations.slice(0,3).map(x=>`<p class="small"><strong>${esc(x.title)}</strong><br><span class="muted">${esc(x.status)}</span></p>`).join('')}<button class="btn full" onclick="navigate('tracking')">Acompanhar doações →</button></div></div><div style="margin:25px 0 70px"><button class="btn secondary" onclick="logout()">Sair da conta</button></div></div>`;}
function changeAuthRole(value){state.authRole=value;render();}
function auth(){const role=state.authRole;const user=role==='instituicao'?'instituicao1':'usuario1';return `<div class="auth-wrap"><div class="auth-art"><span class="eyebrow" style="color:#a7dcaf">Pertencer é fazer parte</span><h1>A solidariedade começa com uma conexão.</h1><p style="color:#c3dfcb;max-width:395px;font-size:17px">Participe de uma rede de pessoas que acreditam no poder de ajudar.</p><div style="font-size:105px;margin-top:20px">🤝</div><div class="small" style="color:#b2d9bc">✳ Conectando boas intenções a necessidades reais.</div></div><div class="auth-box"><div class="eyebrow">Bem-vindo à Conectação</div><h2 style="font-size:32px;margin:8px 0 9px">${state.authTab==='login'?'Que bom ter você aqui!':'Faça parte dessa rede'}</h2><p class="muted small" style="margin-bottom:24px">Acesso simulado, sem cadastro ou envio de dados reais.</p><div class="auth-tab"><button class="${state.authTab==='login'?'active':''}" onclick="state.authTab='login';render()">Entrar</button><button class="${state.authTab==='register'?'active':''}" onclick="state.authTab='register';render()">Criar conta</button></div><form onsubmit="signIn(event)"><div class="field-group"><label class="label" for="authRole">${state.authTab==='login'?'Acessar como':'Cadastrar como'}</label><select class="field" id="authRole" onchange="changeAuthRole(this.value)"><option value="doador" ${role==='doador'?'selected':''}>Doador</option><option value="instituicao" ${role==='instituicao'?'selected':''}>Instituição</option></select></div>${state.authTab==='register'?`<div class="field-group"><label class="label" for="registerName">${role==='instituicao'?'Nome da instituição':'Nome completo'}</label><input id="registerName" class="field" required value="${role==='instituicao'?'Instituto Sementes do Bem':'Mariana Oliveira'}"></div>`:''}<div class="field-group"><label class="label" for="loginUser">Usuário de teste</label><input id="loginUser" class="field" required value="${user}" autocomplete="off"></div><div class="field-group"><label class="label" for="loginPassword">Senha de teste</label><input id="loginPassword" class="field" type="password" required value="123456" minlength="4"></div><div class="callout" style="margin:10px 0"><strong>Credenciais fixas do teste</strong><div>Usuário: <code>${user}</code> · Senha: <code>123456</code></div></div><button class="btn full" style="margin-top:8px" type="submit">${state.authTab==='login'?'Entrar na minha conta':'Criar conta simulada'} →</button></form><p class="muted small" style="text-align:center;margin-top:20px">Os dados são ilustrativos. Nenhuma conta real será criada.</p></div></div>`;}
function signIn(event){event.preventDefault();const user=$('#loginUser')?.value?.trim(),password=$('#loginPassword')?.value,expected=state.authRole==='instituicao'?'instituicao1':'usuario1';if(user!==expected||password!=='123456'){toast('Utilize as credenciais fixas exibidas no formulário.');$('#loginUser').setAttribute('aria-invalid','true');return;}state.role=state.authRole;const target=state.role==='instituicao'?'dashboard':state.pendingNeed?'donate':'explore';const id=state.pendingNeed;state.pendingNeed=null;navigate(target,id);toast(state.role==='instituicao'?'Acesso institucional realizado. Bem-vindo ao painel!':'Acesso de demonstração realizado!');}
function sidebar(){return `<aside class="sidebar"><div class="org"><div class="row"><div class="avatar">🌱</div><div class="org-name"><strong style="font-size:13px">Sementes do Bem</strong><br><small class="muted">Conta da instituição</small></div></div></div><button class="side-link ${state.view==='dashboard'?'active':''}" onclick="navigate('dashboard')">▦ <span class="side-label">Visão geral</span></button><button class="side-link ${state.view==='manage'?'active':''}" onclick="navigate('manage')">♡ <span class="side-label">Doações recebidas</span></button><button class="side-link ${state.view==='create'?'active':''}" onclick="navigate('create')">⊞ <span class="side-label">Nova necessidade</span></button><div class="side-ender">💚 <strong>Obrigado por transformar vidas!</strong><br>Seu trabalho inspira toda a comunidade.</div></aside>`;}
function dashboard(){let act=needs.filter(x=>x.org==='Instituto Sementes do Bem');return `<div class="work-area">${sidebar()}<main class="workspace"><div class="heading"><div><div class="eyebrow">Painel da instituição</div><h1>Olá, equipe Sementes! 👋</h1><div class="muted">Veja o que está acontecendo com sua comunidade hoje.</div></div><button class="btn" onclick="navigate('create')">+ Nova necessidade</button></div><div class="grid4" style="margin-bottom:25px"><div class="card metric-card"><div class="muted small">Necessidades ativas</div><div class="num">${act.length.toString().padStart(2,'0')}</div><span class="tag">Divulgadas</span></div><div class="card metric-card"><div class="muted small">Doações pendentes</div><div class="num">${proposals.filter(x=>x.status==='Pendente').length.toString().padStart(2,'0')}</div><span class="tag urgent">Aguardando resposta</span></div><div class="card metric-card"><div class="muted small">Doações recebidas</div><div class="num">${proposals.filter(x=>x.status==='Recebida').length.toString().padStart(2,'0')}</div><span class="tag">Concluídas</span></div><div class="card metric-card"><div class="muted small">Propostas registradas</div><div class="num">${proposals.length.toString().padStart(2,'0')}</div><span class="tag blue">Comunidade</span></div></div><div class="dashboard-cols"><div class="card"><div class="spread" style="padding:23px 23px 10px"><h3 style="margin:0">Solicitações recentes</h3><button class="btn ghost sm" onclick="navigate('manage')">Ver todas →</button></div><div class="table-card"><table class="table"><thead><tr><th>Doador</th><th>Doação</th><th>Status</th></tr></thead><tbody>${proposals.slice(0,4).map(x=>`<tr><td><strong>${esc(x.name)}</strong><small>${esc(x.date)}</small></td><td>${esc(x.item)}</td><td>${tag(x.status)}</td></tr>`).join('')}</tbody></table></div></div><div class="card" style="padding:24px"><h3>Progresso das necessidades</h3>${act.slice(0,3).map(n=>`<div style="margin:21px 0"><div class="spread"><strong class="small">${esc(n.title)}</strong><span class="muted small">${pct(n)}%</span></div><div class="progress" style="margin-top:12px"><i style="width:${pct(n)}%"></i></div></div>`).join('')}<button class="btn secondary full" onclick="navigate('create')">+ Adicionar necessidade</button></div></div><p class="muted small" style="margin-top:20px">Números e registros fictícios utilizados para fins acadêmicos.</p></main></div>`;}
function instProfile(){const act=needs.filter(n=>n.org==='Instituto Sementes do Bem').length,pending=proposals.filter(x=>x.status==='Pendente').length;return `<div class="container"><div class="profile-back"><button class="btn secondary sm" onclick="navigate('dashboard')">← Voltar ao painel</button></div><section class="profile-hero"><div class="eyebrow">Área da instituição</div><h1>Perfil da instituição</h1><p class="muted">Gerencie sua identificação e acompanhe as atividades da organização.</p></section><div class="card profile-header" style="padding:20px"><div class="avatar" style="background:#153b31;color:#fff">IS</div><div style="flex:1"><h2>${esc(state.instName||'Instituto Sementes do Bem')}</h2><div class="muted small">Instituição · Assistência social · Lavras, MG</div></div><button class="btn" onclick="navigate('instEdit')">Editar perfil ✎</button></div><div class="grid3 profile-stats"><div class="statbox"><strong>${act}</strong><span class="caption">Necessidades ativas</span></div><div class="statbox"><strong>${proposals.length}</strong><span class="caption">Propostas recebidas</span></div><div class="statbox"><strong>${proposals.filter(x=>x.status==='Recebida').length}</strong><span class="caption">Doações concluídas</span></div></div><div class="profile-panel"><div class="card"><h3>Dados institucionais</h3><div class="info-row">Nome: ${esc(state.instName||'Instituto Sementes do Bem')}</div><div class="info-row">CNPJ: 00.000.000/0001-00 (fictício)</div><div class="info-row">E-mail: ${esc(state.instEmail||'contato@sementes.exemplo')}</div><div class="info-row">Telefone: (35) 3821-1000</div><div class="info-row">Endereço: Rua das Acácias, 85 - Centro</div></div><div class="card"><h3>Atividade institucional</h3><p class="small"><strong>Propostas pendentes</strong><br><span class="muted">${pending} aguardando resposta</span></p><p class="small"><strong>Necessidades abertas</strong><br><span class="muted">${act} campanhas ativas</span></p><button class="btn full" onclick="navigate('manage')">Gerenciar doações →</button></div></div><div style="margin:25px 0 60px"><button class="btn secondary" onclick="logout()">Sair da conta</button></div></div>`;}
function instEdit(){return `<div class="container"><div class="profile-back"><button class="btn secondary sm" onclick="navigate('instProfile')">← Voltar ao perfil</button></div><section class="profile-hero"><div class="eyebrow">Área da instituição</div><h1>Editar perfil institucional</h1><p class="muted">Atualize os dados de demonstração da organização.</p></section><form class="card form-card" style="max-width:700px;margin:0 auto 70px" onsubmit="event.preventDefault();state.instName=$('#instName').value.trim();state.instEmail=$('#instEmail').value.trim();navigate('instProfile');toast('Perfil atualizado no protótipo!')"><div class="field-group"><label class="label" for="instName">Nome da instituição</label><input id="instName" class="field" required value="${esc(state.instName||'Instituto Sementes do Bem')}"></div><div class="field-group"><label class="label" for="instEmail">E-mail de contato</label><input id="instEmail" class="field" required type="email" value="${esc(state.instEmail||'contato@sementes.exemplo')}"></div><div class="spread"><button type="button" class="btn secondary" onclick="navigate('instProfile')">Cancelar</button><button class="btn" type="submit">Salvar alterações ✓</button></div></form></div>`;}
function create(){return `<div class="work-area">${sidebar()}<main class="workspace"><div class="heading"><div><div class="eyebrow">Gestão de necessidades</div><h1>Publicar nova necessidade</h1><p class="muted">Conte à comunidade como ela pode ajudar.</p></div></div><div class="form-layout" style="max-width:1120px"><form class="card form-card" onsubmit="submitNewNeed(event)"><h3>Informações da necessidade</h3><div class="field-group"><label class="label" for="newTitle">Título da necessidade *</label><input id="newTitle" class="field" placeholder="Ex.: Kits de higiene para famílias" required></div><div class="field-group"><label class="label" for="newDesc">Descrição *</label><textarea id="newDesc" class="field" required placeholder="Explique o que é necessário, para quem é e por que essa contribuição é importante..."></textarea><small class="muted">Informe quantidades e condições necessárias.</small></div><div class="formgrid"><div class="field-group"><label class="label" for="newKind">Tipo de doação *</label><select id="newKind" class="field"><option>Itens</option><option>Serviços</option><option>Financeira</option></select></div><div class="field-group"><label class="label" for="newCategory">Categoria *</label><select id="newCategory" class="field">${['Alimentos','Higiene','Educação','Saúde','Vestuário','Serviços','Meio ambiente','Outros'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field-group"><label class="label" for="newGoal">Quantidade ou meta *</label><input id="newGoal" class="field" type="number" min="1" placeholder="Ex.: 50" required></div><div class="field-group"><label class="label" for="newUrgency">Prioridade *</label><select id="newUrgency" class="field"><option>Moderada</option><option>Alta prioridade</option></select></div><div class="field-group"><label class="label" for="newDeadline">Prazo desejado</label><input id="newDeadline" class="field" type="date"></div><div class="field-group"><label class="label" for="newReceipt">Local de recebimento</label><select id="newReceipt" class="field"><option>Endereço da instituição</option><option>A combinar</option></select></div></div><div class="divider"></div><div class="spread"><button class="btn secondary" type="button" onclick="navigate('dashboard')">Cancelar</button><button class="btn" type="submit">Publicar necessidade →</button></div></form><aside class="card side-card" style="position:static"><h3>💡 Dicas para uma boa publicação</h3><p class="small muted">Descrições claras ajudam os doadores a entender exatamente o que a instituição precisa.</p><div class="info-row">✓ Explique quem será beneficiado</div><div class="info-row">✓ Defina uma meta objetiva</div><div class="info-row">✓ Informe condições de recebimento</div><div class="divider"></div><p class="small muted">O registro será adicionado apenas a esta sessão simulada, e ficará visível ao explorar necessidades.</p></aside></div></main></div>`;}
function submitNewNeed(event){event.preventDefault();const id=Math.max(...needs.map(n=>n.id))+1;const title=$('#newTitle').value.trim(),desc=$('#newDesc').value.trim(),cat=$('#newCategory').value,urg=$('#newUrgency').value,kind=$('#newKind').value,total=Number($('#newGoal').value);if(!title||!desc||!(total>0)){toast('Preencha os campos obrigatórios corretamente.');return;}needs.unshift({id,title,org:'Instituto Sementes do Bem',cat,urg,kind,city:'Lavras, MG',qty:0,total,emoji:kind==='Financeira'?'💚':kind==='Serviços'?'🤝':'📦',bg:'#e5f1e8',desc});navigate('dashboard');toast('Necessidade publicada nesta sessão de demonstração!');}
function manage(){const pending=proposals.filter(x=>x.status==='Pendente').length,received=proposals.filter(x=>x.status==='Recebida').length;return `<div class="work-area">${sidebar()}<main class="workspace"><div class="heading"><div><div class="eyebrow">Gestão de doações</div><h1>Doações recebidas</h1><p class="muted">Acompanhe, confirme e organize cada gesto de solidariedade.</p></div><button class="btn secondary" onclick="navigate('dashboard')">← Voltar ao painel</button></div><div class="grid3" style="margin-bottom:25px"><div class="statbox"><div class="caption">Total de propostas</div><strong>${proposals.length}</strong></div><div class="statbox"><div class="caption">Aguardando confirmação</div><strong>${pending}</strong></div><div class="statbox"><div class="caption">Recebidas</div><strong>${received}</strong></div></div><div class="card"><div class="spread" style="padding:22px"><h3 style="margin:0">Solicitações da comunidade</h3><select id="statusfilter" class="field" style="width:210px" aria-label="Filtrar propostas por status" onchange="filterProposals(this.value)"><option>Todos</option><option>Pendente</option><option>Confirmada</option><option>Recebida</option><option>Recusada</option></select></div><div class="table-card"><table class="table"><thead><tr><th>Identificador</th><th>Doador</th><th>Necessidade</th><th>Data</th><th>Status</th><th>Ações</th></tr></thead><tbody>${proposals.map((x,i)=>`<tr data-status="${esc(x.status)}"><td>${esc(x.id)}</td><td><strong>${esc(x.name)}</strong><small>${esc(x.amount)}</small></td><td>${esc(x.item)}</td><td>${esc(x.date)}</td><td>${tag(x.status)}</td><td>${x.status==='Pendente'?`<button class="btn sm" onclick="updateProposal(${i},'Confirmada')">Aceitar</button> <button class="btn ghost sm" onclick="updateProposal(${i},'Recusada')">Recusar</button>`:x.status==='Confirmada'?`<button class="btn sm" onclick="updateProposal(${i},'Recebida')">Confirmar recebimento</button>`:`<span class="small muted">Concluído</span>`}</td></tr>`).join('')}</tbody></table></div></div><p class="muted small" style="margin-top:17px">Dados fictícios. As ações alteram apenas esta sessão de demonstração.</p></main></div>`;}
function filterProposals(value){document.querySelectorAll('[data-status]').forEach(x=>x.style.display=value==='Todos'||x.dataset.status===value?'':'none');}
function updateProposal(i,status){const p=proposals[i];if(!p)return;p.status=status;if(p.historyId){const h=donations.find(d=>d.id===p.historyId);if(h)h.status=status;}render();toast('Status da proposta atualizado para '+status+'.');}
function render(){const views={home,explore,institutions:institutionsPage,institution,need:needDetail,donate,tracking,donorProfile,auth,dashboard,create,manage,instProfile,instEdit};const secured=['dashboard','create','manage','instProfile','instEdit'];if(secured.includes(state.view)&&state.role!=='instituicao')state.view='auth';if(state.view==='donate'&&state.role!=='doador')state.view='auth';if(state.role==='instituicao'&&!secured.includes(state.view)&&state.view!=='auth')state.view='dashboard';const content=views[state.view]||home;const isInstitution=state.role==='instituicao'&&secured.includes(state.view);$('#app').innerHTML=header()+`<main class="view">${content()}</main>`+(isInstitution?'':footer())+historyModal();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.openHistory)closeModal();});
